package com.nbi.hateoas.dto;

import java.math.BigDecimal;

public class AccountDto {
    private String accountId;
    private String holderName;
    private BigDecimal balance;
    private String status; // ACTIVE or FROZEN

    public AccountDto(String accountId, String holderName, BigDecimal balance, String status) {
        this.accountId = accountId; this.holderName = holderName;
        this.balance = balance; this.status = status;
    }
    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getStatus() { return status; }
    public boolean isActive() { return "ACTIVE".equals(status); }
}
```

