package com.nbi.hateoas.service;

import com.nbi.hateoas.dto.AccountDto;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class AccountService {
    private final Map<String, AccountDto> store = new HashMap<>();

    public AccountService() {
        store.put("SAV2001", new AccountDto("SAV2001", "Rajesh Kumar",
                new BigDecimal("1000000.00"), "ACTIVE"));
        store.put("CUR3001", new AccountDto("CUR3001", "Priya Sharma",
                new BigDecimal("250000.00"), "FROZEN"));
    }
    public Optional<AccountDto> get(String id) { return Optional.ofNullable(store.get(id)); }
}
