// ─── File: src/main/java/com/nbi/hateoas/controller/AccountController.java ───
package com.nbi.hateoas.controller;

import com.nbi.hateoas.dto.AccountDto;
import com.nbi.hateoas.service.AccountService;
import org.springframework.hateoas.EntityModel;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.*;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    @GetMapping("/{id}")
    public ResponseEntity<EntityModel<AccountDto>> get(@PathVariable String id) {
        return service.get(id).map(dto -> {
            EntityModel<AccountDto> model = EntityModel.of(dto);
            // Always available links:
            model.add(linkTo(methodOn(AccountController.class).get(id)).withSelfRel());
            model.add(linkTo(methodOn(AccountController.class).transactions(id)).withRel("transactions"));
            // STATE-DRIVEN links: present only when the action is actually allowed.
            if (dto.isActive()) {
                model.add(linkTo(methodOn(AccountController.class).transfer(id)).withRel("transfer"));
                model.add(linkTo(methodOn(AccountController.class).freeze(id)).withRel("freeze"));
            } else {
                model.add(linkTo(methodOn(AccountController.class).unfreeze(id)).withRel("unfreeze"));
            }
            return ResponseEntity.ok(model);
        }).orElse(ResponseEntity.notFound().build());
    }

    // Target endpoints for the links (bodies omitted for brevity).
    @GetMapping("/{id}/transactions")
    public ResponseEntity<String> transactions(@PathVariable String id) {
        return ResponseEntity.ok("transactions for " + id);
    }
    @PostMapping("/{id}/transfers")
    public ResponseEntity<String> transfer(@PathVariable String id) {
        return ResponseEntity.ok("transfer from " + id);
    }
    @PostMapping("/{id}/freeze")
    public ResponseEntity<String> freeze(@PathVariable String id) {
        return ResponseEntity.ok("frozen " + id);
    }
    @PostMapping("/{id}/unfreeze")
    public ResponseEntity<String> unfreeze(@PathVariable String id) {
        return ResponseEntity.ok("unfrozen " + id);
    }
}
```
